// spec: .qa/e2e/specs/home.md (3.1)
// seed: tests/seed.user.spec.ts
// @data: создаёт 1 прерванный сеанс мониторинга с 2 сбоями (удалить нельзя). Запускать по одному.
import { test, expect, type Page } from '@playwright/test';
import path from 'node:path';
import { startMonitoring } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(180_000);

const clean = (s: string) => s.replace(/[‎‏⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();
const hhmm = (d: Date) => `${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`;

async function readRow(row: ReturnType<Page['getByRole']>) {
  return row.evaluate((el) => ({ text: (el as HTMLElement).innerText, icon: el.querySelector('svg path')?.getAttribute('d') ?? '' }));
}

test.describe('Главная — прерванный сеанс первым', () => {
  test('Прерванный сеанс с 2 сбоями первым в «ניטורים אחרונים» и в «היסטוריה», «2 כשלים» #09b2de78 @iphone @data', async ({ page }) => {
    // Допустимое время старта: от минуты до запуска до минуты после выхода на /monitor/live
    const before = new Date();
    // 1. Мониторинг со сбоем «המכשיר זז» (мок moved — только веб: ?mock в адресе)
    await startMonitoring(page, 'moved');
    const after = new Date();
    const allowed = new Set<string>();
    for (let t = before.getTime() - 60_000; t <= after.getTime() + 60_000; t += 30_000) allowed.add(hhmm(new Date(t)));

    // 2–3. Два сбоя: «המכשיר זז» → «כיוון מחדש» → «חזרה לניטור» → /monitor/live
    for (let i = 1; i <= 2; i++) {
      await expect(page.getByText('המכשיר זז').filter({ visible: true }).first(), `сбой ${i}`).toBeVisible({ timeout: 45_000 });
      await page.getByRole('button', { name: 'כיוון מחדש' }).filter({ visible: true }).click();
      await page.getByRole('button', { name: 'חזרה לניטור' }).filter({ visible: true }).click();
      await expect(page).toHaveURL(/\/monitor\/live/);
      await expect(page.getByRole('button', { name: 'חזרה לניטור' }).filter({ visible: true })).toHaveCount(0);
    }

    // 4. Не завершая мониторинг, «закрыть приложение».
    // только веб: уход со страницы в той же вкладке вместо закрытия приложения (вторую вкладку на сохранённой сессии не открываем — L-20261008-5).
    await page.goto('/home');

    // 5. «ניטורים אחרונים»: первая строка — сегодня, время старта, «2 כשלים»
    await expect(page.getByRole('heading', { name: 'ניטורים אחרונים' }).filter({ visible: true })).toBeVisible();
    const homeRow = page.getByRole('button', { name: /דק׳ · / }).filter({ visible: true }).first();
    await expect(homeRow).toContainText('2 כשלים');
    const home = await readRow(homeRow);
    const homeText = clean(home.text);
    const time = /^היום, (\d{1,2}:\d{2})/.exec(homeText)?.[1];
    expect(time, `первая строка «${homeText}»: «היום, HH:MM»`).toBeTruthy();
    expect([...allowed], `время старта ${time}`).toContain(time);
    expect(homeText).toMatch(/2 כשלים$/);
    expect(homeText).not.toContain('בלי התרעות');

    // 6. «היסטוריה»: первая запись — то же время, «2 כשלים», та же иконка
    await page.getByRole('tab', { name: 'היסטוריה' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/history/);
    const histRow = page.getByRole('button', { name: /ניטור, / }).filter({ visible: true }).first();
    await expect(histRow).toContainText(time!);
    const hist = await readRow(histRow);
    expect(clean(hist.text)).toMatch(/2 כשלים$/);
    expect(hist.icon, 'иконка совпадает с «ניטורים אחרונים»').toBe(home.icon);
  });
});
